-- None required: UUID defaults use the built-in gen_random_uuid() (PostgreSQL 13+).
CREATE SCHEMA IF NOT EXISTS __mj;
SET search_path TO __mj, public;
SET standard_conforming_strings = on;

/* ============================================================================= */
/* Migration: Wave 0.1 — Canon Full-Run Schema */
/* Version:   v6.3.x */
/* Target:    MemberJunction Core (__mj) */
/* Purpose: */
/*   1. Add __mj.GraphPermission for per-graph Read / Use / Approve access control. */
/*   2. Add __mj.SearchScopeGraph for dedicated SearchScope -> Graph lane bindings. */
/*   3. Deliver MJ 6213 memory & learning-cycle schema additions: */
/*      - __mj.AIAgentNoteSource + OPENJSON / ConsolidatedIntoNoteID backfill */
/*      - Additive cycle telemetry columns on __mj.AIAgentLearningCycle */
/*      - __mj.AIAgentLearningCycleProposal (quarantine ledger, Self-Improvement Memory, Rule 6 scoring/routing/briefs) */
/*      - __mj.AIAgentLearningCycleProposalSource (exclusive-arc real FKs + polymorphic escape hatch) */
/*      - __mj.AIAgentContextItem (per-run and per-session retrieval/citation traces) */
/*      - Canon authority columns on __mj.AIAgentNote and __mj.AISkill */
/*      - AllowInFlightMemorySearch flag on __mj.AIAgent */
/*   4. Add nullable EffectiveFrom / EffectiveTo validity window columns on __mj.GraphConcept. */
/*   5. Add nullable AuthorityTierID override column on __mj.GraphEdge. */
/*   6. Extend CK_GraphConcept_Status and CK_GraphEdge_Status to include 'Provisional'. */
/*   7. Add StaleMemberPolicy and PublishNonHumanApprovals settings on __mj.Graph. */
/*   8. Update spDeleteEntityWithCoreDependencies for new Entity FKs and dependent child tables. */
/* ============================================================================= */
/* ============================================================================= */
/* 1. GraphPermission */
/* ============================================================================= */
CREATE TABLE __mj."GraphPermission" (
  "ID" UUID NOT NULL DEFAULT (
    GEN_RANDOM_UUID()
  ),
  "GraphID" UUID NOT NULL,
  "UserID" UUID NULL,
  "RoleID" UUID NULL,
  "PermissionLevel" VARCHAR(20) NOT NULL,
  CONSTRAINT "PK_GraphPermission" PRIMARY KEY ("ID"),
  CONSTRAINT "FK_GraphPermission_Graph" FOREIGN KEY ("GraphID") REFERENCES __mj."Graph" (
    "ID"
  ),
  CONSTRAINT "FK_GraphPermission_User" FOREIGN KEY ("UserID") REFERENCES __mj."User" (
    "ID"
  ),
  CONSTRAINT "FK_GraphPermission_Role" FOREIGN KEY ("RoleID") REFERENCES __mj."Role" (
    "ID"
  ),
  CONSTRAINT "CK_GraphPermission_Level" CHECK ("PermissionLevel" IN ('None', 'Read', 'Use', 'Approve')),
  CONSTRAINT "CK_GraphPermission_Principal" CHECK ((
    NOT "UserID" IS NULL AND "RoleID" IS NULL
  )
  OR (
    "UserID" IS NULL AND NOT "RoleID" IS NULL
  ))
);

CREATE UNIQUE INDEX "UX_GraphPermission_Graph_User" ON __mj."GraphPermission"("GraphID", "UserID") NULLS NOT DISTINCT
WHERE
  (
    NOT "UserID" IS NULL
  );

CREATE UNIQUE INDEX "UX_GraphPermission_Graph_Role" ON __mj."GraphPermission"("GraphID", "RoleID") NULLS NOT DISTINCT
