/* ============================================================================= */
/* 3.1 AIAgentNoteSource + Backfill from DerivedFromNoteIDs & ConsolidatedIntoNoteID */
/* ============================================================================= */
CREATE TABLE __mj."AIAgentNoteSource" (
  "ID" UUID NOT NULL DEFAULT (
    GEN_RANDOM_UUID()
  ),
  "NoteID" UUID NOT NULL,
  "SourceNoteID" UUID NOT NULL,
  "RelationshipType" VARCHAR(30) NOT NULL DEFAULT (
    'Consolidated From'
  ),
  "Sequence" INT NOT NULL DEFAULT (
    (
      0
    )
  ),
  CONSTRAINT "PK_AIAgentNoteSource" PRIMARY KEY ("ID"),
  CONSTRAINT "FK_AIAgentNoteSource_Note" FOREIGN KEY ("NoteID") REFERENCES __mj."AIAgentNote" (
    "ID"
  ),
  CONSTRAINT "FK_AIAgentNoteSource_SourceNote" FOREIGN KEY ("SourceNoteID") REFERENCES __mj."AIAgentNote" (
    "ID"
  ),
  CONSTRAINT "UQ_AIAgentNoteSource_Edge" UNIQUE NULLS NOT DISTINCT (
    "NoteID",
    "SourceNoteID",
    "RelationshipType"
  ),
  CONSTRAINT "CK_AIAgentNoteSource_NoSelfLoop" CHECK ("NoteID" <> "SourceNoteID"),
  CONSTRAINT "CK_AIAgentNoteSource_RelType" CHECK ("RelationshipType" IN (
    'Consolidated From',
    'Supersedes',
    'Disambiguated From',
    'Dream Synthesized From',
    'Other'
  ))
);

WITH "DerivedPairs" AS (
  SELECT
    "n"."ID" AS "NoteID",
    "src"."ID" AS "SourceNoteID",
    MIN(("j"."ord"::INT - 1)) AS "Sequence"
  FROM __mj."AIAgentNote" AS "n"
  CROSS JOIN LATERAL jsonb_array_elements_text(
    CASE
      WHEN "n"."DerivedFromNoteIDs" IS NOT NULL
       AND LEFT(LTRIM("n"."DerivedFromNoteIDs"), 1) = '['
       AND pg_input_is_valid("n"."DerivedFromNoteIDs", 'jsonb')
       AND jsonb_typeof("n"."DerivedFromNoteIDs"::jsonb) = 'array'
      THEN "n"."DerivedFromNoteIDs"::jsonb
      ELSE '[]'::jsonb
    END
  ) WITH ORDINALITY AS "j"("val", "ord")
  INNER JOIN __mj."AIAgentNote" AS "src"
    ON (
      CASE
        WHEN "j"."val" ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN "j"."val"::uuid
        ELSE NULL
      END
    ) = "src"."ID"
  WHERE
    NOT "n"."DerivedFromNoteIDs" IS NULL
    AND "n"."ID" <> "src"."ID"
  GROUP BY
    "n"."ID",
    "src"."ID"
)
INSERT INTO __mj."AIAgentNoteSource" (
  "NoteID",
  "SourceNoteID",
  "RelationshipType",
  "Sequence"
)
SELECT
  "dp"."NoteID",
  "dp"."SourceNoteID",
  'Consolidated From',
  "dp"."Sequence"
FROM "DerivedPairs" AS "dp"
WHERE
  NOT EXISTS(
    SELECT
      1
    FROM __mj."AIAgentNoteSource" AS "existing"
    WHERE
      "existing"."NoteID" = "dp"."NoteID"
      AND "existing"."SourceNoteID" = "dp"."SourceNoteID"
      AND "existing"."RelationshipType" = 'Consolidated From'
  );

INSERT INTO __mj."AIAgentNoteSource" (
  "NoteID",
  "SourceNoteID",
  "RelationshipType",
  "Sequence"
)
SELECT
  "src"."ConsolidatedIntoNoteID",
  "src"."ID",
  'Consolidated From',
  0
FROM __mj."AIAgentNote" AS "src"
INNER JOIN __mj."AIAgentNote" AS "target"
  ON "target"."ID" = "src"."ConsolidatedIntoNoteID"
WHERE
  NOT "src"."ConsolidatedIntoNoteID" IS NULL
  AND "src"."ID" <> "src"."ConsolidatedIntoNoteID"
  AND NOT EXISTS(
    SELECT
      1
    FROM __mj."AIAgentNoteSource" AS "existing"
    WHERE
      "existing"."NoteID" = "src"."ConsolidatedIntoNoteID"
      AND "existing"."SourceNoteID" = "src"."ID"
      AND "existing"."RelationshipType" = 'Consolidated From'
  );

