    "ID"
  ),
  CONSTRAINT "CK_ProposalSource_Role" CHECK ("Role" IN (
    'Supporting Note',
    'Contradicting Note',
    'Failed Run',
    'Exemplar Run',
    'User Correction',
    'Bridge Node',
    'Other'
  )),
  CONSTRAINT "CK_ProposalSource_TrustTier" CHECK ("TrustTierAtSnapshot" IN ('Untrusted External', 'Provisional User', 'Verified Active', 'Canonical')),
  CONSTRAINT "CK_ProposalSource_PolymorphicPair" CHECK ((
    "SourceEntityID" IS NULL AND "SourceRecordID" IS NULL
  )
  OR (
    NOT "SourceEntityID" IS NULL AND NOT "SourceRecordID" IS NULL
  )),
  CONSTRAINT "CK_ProposalSource_OneTarget" CHECK ((
    CASE WHEN NOT "SourceNoteID" IS NULL THEN 1 ELSE 0 END
  ) + (
    CASE WHEN NOT "SourceAgentRunID" IS NULL THEN 1 ELSE 0 END
  ) + (
    CASE WHEN NOT "SourceConversationDetailID" IS NULL THEN 1 ELSE 0 END
  ) + (
    CASE WHEN NOT "SourceGraphConceptID" IS NULL THEN 1 ELSE 0 END
  ) + (
    CASE WHEN NOT "SourceGraphEdgeID" IS NULL THEN 1 ELSE 0 END
  ) + (
    CASE
      WHEN NOT "SourceEntityID" IS NULL AND NOT "SourceRecordID" IS NULL
      THEN 1
      ELSE 0
    END
  ) = 1)
);

