  ADD COLUMN "IsCanonical" BOOLEAN NOT NULL DEFAULT FALSE,
  ADD COLUMN "CanonApprovedByUserID" UUID NULL CONSTRAINT "FK_AIAgentNote_CanonApprovedByUser" REFERENCES __mj."User" (
    "ID"
  ),
  ADD COLUMN "CanonApprovedAt" TIMESTAMPTZ NULL,
  ADD COLUMN "OriginProposalID" UUID NULL CONSTRAINT "FK_AIAgentNote_OriginProposal" REFERENCES __mj."AIAgentLearningCycleProposal" (
    "ID"
  )
 /* ============================================================================= */ /* 3.6 Canon Authority Columns on AIAgentNote & AISkill + AIAgent Flag */ /* ============================================================================= */;

ALTER TABLE __mj."AISkill"
  ADD COLUMN "IsCanonical" BOOLEAN NOT NULL DEFAULT FALSE,
  ADD COLUMN "CanonApprovedByUserID" UUID NULL CONSTRAINT "FK_AISkill_CanonApprovedByUser" REFERENCES __mj."User" (
    "ID"
  ),
  ADD COLUMN "CanonApprovedAt" TIMESTAMPTZ NULL,
  ADD COLUMN "OriginProposalID" UUID NULL CONSTRAINT "FK_AISkill_OriginProposal" REFERENCES __mj."AIAgentLearningCycleProposal" (
    "ID"
  );

ALTER TABLE __mj."AIAgent"
ADD COLUMN "AllowInFlightMemorySearch" BOOLEAN NOT NULL DEFAULT FALSE;

ALTER TABLE __mj."GraphConcept"
  ADD COLUMN "EffectiveFrom" TIMESTAMPTZ NULL,
  ADD COLUMN "EffectiveTo" TIMESTAMPTZ NULL,
  ADD CONSTRAINT "CK_GraphConcept_EffectiveDates" CHECK ("EffectiveFrom" IS NULL
  OR "EffectiveTo" IS NULL
  OR "EffectiveFrom" <= "EffectiveTo")
 /* ============================================================================= */ /* 4. GraphConcept EffectiveFrom / EffectiveTo */ /* ============================================================================= */;

ALTER TABLE __mj."GraphEdge"
  ADD COLUMN "AuthorityTierID" UUID NULL CONSTRAINT "FK_GraphEdge_GraphAuthorityTier" REFERENCES __mj."GraphAuthorityTier" (
    "ID"
  )
 /* ============================================================================= */ /* 5. GraphEdge AuthorityTierID */ /* ============================================================================= */;

ALTER TABLE __mj."GraphConcept"
DROP CONSTRAINT "CK_GraphConcept_Status" /* ============================================================================= */ /* 6. Extend GraphConcept.Status & GraphEdge.Status to include 'Provisional' */ /* ============================================================================= */;

ALTER TABLE __mj."GraphConcept"
  ADD CONSTRAINT "CK_GraphConcept_Status" CHECK ("Status" IN ('Draft', 'Proposed', 'Provisional', 'Approved', 'Deprecated'));

ALTER TABLE __mj."GraphEdge"
DROP CONSTRAINT "CK_GraphEdge_Status";

ALTER TABLE __mj."GraphEdge"
  ADD CONSTRAINT "CK_GraphEdge_Status" CHECK ("Status" IN ('Proposed', 'Provisional', 'Approved', 'Rejected'));

ALTER TABLE __mj."Graph"
  ADD COLUMN "StaleMemberPolicy" VARCHAR(30) NOT NULL DEFAULT (
    'Hide'
  ) CONSTRAINT "CK_Graph_StaleMemberPolicy" CHECK ("StaleMemberPolicy" IN ('Hide', 'Show With Warning')),
  ADD COLUMN "PublishNonHumanApprovals" BOOLEAN NOT NULL DEFAULT FALSE
 /* ============================================================================= */ /* 7. Graph StaleMemberPolicy & PublishNonHumanApprovals */ /* ============================================================================= */;

COMMENT ON TABLE __mj."GraphPermission" IS 'Per-user or per-role permission grant on a semantic Graph. Exactly one of UserID or RoleID is set on each row; PermissionLevel is None, Read, Use, or Approve.';

COMMENT ON COLUMN __mj."GraphPermission"."PermissionLevel" IS 'Grant level on the graph: None, Read, Use, or Approve.';

COMMENT ON TABLE __mj."SearchScopeGraph" IS 'Binds a SearchScope to a semantic Graph as a first-class retrieval lane with Priority ordering and an optional MaxResults cap.';

COMMENT ON COLUMN __mj."SearchScopeGraph"."Priority" IS 'Relative retrieval priority across graphs bound to the same SearchScope; lower values are queried first.';

COMMENT ON COLUMN __mj."SearchScopeGraph"."MaxResults" IS 'Optional per-graph result cap within the SearchScope retrieval lane.';

COMMENT ON TABLE __mj."AIAgentNoteSource" IS 'Relational lineage edges linking consolidated or synthesized AI Agent Notes back to their upstream source notes.';

COMMENT ON COLUMN __mj."AIAgentNoteSource"."RelationshipType" IS 'Provenance relationship kind: Consolidated From, Supersedes, Disambiguated From, Dream Synthesized From, or Other.';

COMMENT ON COLUMN __mj."AIAgentNoteSource"."Sequence" IS 'Zero-based ordering position among source notes contributing to the derived note.';

COMMENT ON COLUMN __mj."AIAgentLearningCycle"."CycleType" IS 'Classification of the learning cycle pass: Consolidation, Dreaming, Skill Extraction, Harness Refinement, or Mixed.';

COMMENT ON COLUMN __mj."AIAgentLearningCycle"."ProposalsGenerated" IS 'Count of candidate proposals generated during this learning cycle.';

COMMENT ON COLUMN __mj."AIAgentLearningCycle"."ProposalsVerified" IS 'Count of proposals verified by replay or deterministic checks during this learning cycle.';

COMMENT ON COLUMN __mj."AIAgentLearningCycle"."ProposalsApplied" IS 'Count of proposals materialized/applied to live records during this learning cycle.';

COMMENT ON COLUMN __mj."AIAgentLearningCycle"."TotalCostUSD" IS 'Total LLM and execution cost in USD incurred by this learning cycle.';

COMMENT ON TABLE __mj."AIAgentLearningCycleProposal" IS 'Quarantine ledger and RL/Rule-6 promotion workbench for candidate notes, skills, graph concepts/edges, and harness revisions.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."PrimaryScopeRecordID" IS 'Record identifier within PrimaryScopeEntityID when the proposal is scoped to a single entity record.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."SecondaryScopes" IS 'Optional JSON specification matching ScopedPromptPart/AIAgentNote SecondaryScopes isolation filters.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ProposalType" IS 'Kind of change proposed (Create Note, Supersede Notes, Promote To Canon, Draft Skill, Create Graph Edge, Create Canon Concept, Promote Workflow, Evolve Workflow, Resolve Graph Contradiction, Prompt Revision).';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."SamplerStrategy" IS 'Sampler or generator pipeline stage that discovered this candidate proposal.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."Title" IS 'Concise human-readable title summarizing the proposed change.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."Claim" IS 'Core factual or behavioral claim asserted by this proposal.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."TestablePrediction" IS 'Optional falsifiable prediction describing how downstream evaluation should improve if this proposal holds.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ProposedPayload" IS 'Structured JSON payload consumed by the deterministic materializer when the proposal is applied.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ClaimHash" IS 'SHA-256 hash of the canonicalized claim used for deduplication and anti-redreaming lookup.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."SourceTrustCeiling" IS 'Monotonic minimum trust tier across all attached proposal sources.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."DistinctUserCount" IS 'Number of distinct users represented in the supporting evidence (for k-anonymity cross-user promotion rules).';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."GeneratorMetadata" IS 'JSON metadata describing candidate generation prompts, temperatures, and ensemble members.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."CrossModelAgreementCount" IS 'Count of independent proposer models agreeing on this claim.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."IsSingleModelOutlier" IS 'True if surfaced by a single high-temperature outlier generator rather than consensus.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."GateProbability" IS 'Pre-verification admission probability assigned by the proposal gate (0.0000 to 1.0000).';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."FalsifierVerdict" IS 'Result from the falsifier check: Passed, Rejected, or Needs Scope Narrowing.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."FalsifierCritique" IS 'Detailed critique explaining why the falsifier rejected or requested scope narrowing.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."VerificationMethod" IS 'Verification mechanism used for this proposal: Counterfactual Replay, Query Check, Hybrid, Manual Only, or None.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ReplayTrialsCount" IS 'Number of counterfactual replay trials executed.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ReplayWinsCount" IS 'Number of replay trials won with this proposal active.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ReplayLossesCount" IS 'Number of replay trials lost with this proposal active.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ReplayWinDelta" IS 'Net win-rate delta observed across paired counterfactual replay trials.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."QueryCheckPassed" IS 'Outcome of deterministic SQL/query verification checks when applicable.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."VerificationEvidence" IS 'Structured JSON verification evidence linking paired trial prompt runs, judges, and query outputs.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ProblemKey" IS 'Normalized recurring problem key grouping prior attempts for Self-Improvement Memory retrieval.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ProblemSummary" IS 'Human-readable description of the underlying problem targeted by this proposal.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."Rationale" IS 'Proposer rationale explaining why this edit is expected to improve outcomes.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."PredictedEffect" IS 'Proposer forecast of expected metric improvement prior to verification.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ObservedEffect" IS 'Measured metric effect observed during verification or post-promotion evaluation.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."EffectMetric" IS 'Name of the metric quantified by PredictedEffect and ObservedEffect.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."EvaluationContext" IS 'JSON snapshot of model, vendor, prompt version, agent config, cohort, and sample size under which effects were measured.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ImpactLevel" IS 'Rule 6 computed impact classification: Low, Medium, High, or Critical.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ImpactInputs" IS 'JSON capture of exact inputs that produced ImpactLevel.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ConfidenceScore" IS 'Rule 6 computed evidence confidence score (0.0000 to 1.0000).';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ConfidenceInputs" IS 'JSON capture of exact evidence inputs that produced ConfidenceScore.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."PromotionRoute" IS 'Selected Rule 6 promotion route: Approved by Policy, Provisional, Human, or Named Owner.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ReviewByDate" IS 'Deadline by which a Provisional approval must be ratified, re-evaluated, or withdrawn.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."ReviewBrief" IS 'JSON or structured markdown review brief presenting evidence, dependents, and pros/cons to reviewers.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."AIReviewerDecision" IS 'AI reviewer recommendation: Approve, Reject, or Needs Revision.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."AIReviewerRationale" IS 'Written rationale recorded by the independent AI reviewer model.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."AIReviewerConfidence" IS 'Confidence score reported by the AI reviewer model (0.0000 to 1.0000).';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."AIReviewedAt" IS 'Timestamp when the AI reviewer evaluation completed.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."HumanOverruleReason" IS 'Human reviewer explanation captured when overruling the AI reviewer recommendation or policy route.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."Status" IS 'Proposal lifecycle status (Draft, Filtered Out, Verifying, Verification Failed, Awaiting Approval, Approved, Applied, Rejected, or Rolled Back).';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."AppliedRecordID" IS 'Polymorphic applied record ID paired with AppliedEntityID when the materialized target is outside the dedicated FK columns.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposal"."AppliedAt" IS 'Timestamp when the approved proposal was materialized to target records.';

COMMENT ON TABLE __mj."AIAgentLearningCycleProposalSource" IS 'Provenance evidence links attaching notes, agent runs, conversation turns, graph concepts/edges, or polymorphic records to a Learning Cycle Proposal.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposalSource"."Role" IS 'Evidentiary role of this source: Supporting Note, Contradicting Note, Failed Run, Exemplar Run, User Correction, Bridge Node, or Other.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposalSource"."TrustTierAtSnapshot" IS 'Trust tier snapshot recorded when the source was attached to the proposal.';

COMMENT ON COLUMN __mj."AIAgentLearningCycleProposalSource"."SourceRecordID" IS 'Polymorphic source record ID paired with SourceEntityID when the source is outside the dedicated FK columns.';

COMMENT ON TABLE __mj."AIAgentContextItem" IS 'Per-execution context exposure, holdout, and citation telemetry trace linking loop runs and realtime sessions to retrieved/injected items.';

COMMENT ON COLUMN __mj."AIAgentContextItem"."EventType" IS 'Context telemetry event kind: Retrieved, Injected, Withheld, Cited, or Other.';

COMMENT ON COLUMN __mj."AIAgentContextItem"."ItemType" IS 'Context item classification: Note, Example, Skill, Graph Concept, Scoped Prompt Part, or Other.';

COMMENT ON COLUMN __mj."AIAgentContextItem"."ItemRecordID" IS 'Polymorphic target record ID paired with ItemEntityID for item types without dedicated FK columns.';

COMMENT ON COLUMN __mj."AIAgentContextItem"."ShortID" IS 'Compact reference identifier rendered into the prompt so cited items resolve reliably.';

COMMENT ON COLUMN __mj."AIAgentContextItem"."Rank" IS 'Zero-based or 1-based display rank position within the assembled context block.';

COMMENT ON COLUMN __mj."AIAgentContextItem"."Similarity" IS 'Vector similarity score captured during semantic retrieval when available.';

COMMENT ON COLUMN __mj."AIAgentContextItem"."Details" IS 'Structured JSON telemetry details conforming to IAgentContextItemDetails (strategy, lane, scores, snapshot flags, citation source).';

COMMENT ON COLUMN __mj."AIAgentNote"."IsCanonical" IS 'True when this note has been ratified as authoritative organizational behavioral Canon.';

COMMENT ON COLUMN __mj."AIAgentNote"."CanonApprovedAt" IS 'Timestamp when this note was approved into organizational Canon.';

COMMENT ON COLUMN __mj."AISkill"."IsCanonical" IS 'True when this skill has been ratified as authoritative organizational procedural Canon.';

COMMENT ON COLUMN __mj."AISkill"."CanonApprovedAt" IS 'Timestamp when this skill was approved into organizational Canon.';

COMMENT ON COLUMN __mj."AIAgent"."AllowInFlightMemorySearch" IS 'When 1, permits the agent to invoke in-flight memory search tools during a run; off by default.';

COMMENT ON COLUMN __mj."GraphConcept"."EffectiveFrom" IS 'Optional inclusive start timestamp from which this concept takes effect for date-scoped Canon queries.';

COMMENT ON COLUMN __mj."GraphConcept"."EffectiveTo" IS 'Optional inclusive end timestamp after which this concept is superseded/expired for date-scoped Canon queries.';

/* GraphEdge AuthorityTierID + updated Status description */;

COMMENT ON COLUMN __mj."GraphEdge"."AuthorityTierID" IS 'Optional foreign key to GraphAuthorityTier overriding the source authority tier for this specific edge.';

/* Graph StaleMemberPolicy & PublishNonHumanApprovals */;

COMMENT ON COLUMN __mj."Graph"."StaleMemberPolicy" IS 'Default handling and ceiling for stale fingerprinted Canon members on this graph: Hide (default) or Show With Warning.';

COMMENT ON COLUMN __mj."Graph"."PublishNonHumanApprovals" IS 'When 1, permits concepts approved by policy or AI reviewer to publish to readers who cannot see underlying sources; off by default.';


COMMENT ON COLUMN __mj."GraphConcept"."Status" IS 'Governance lifecycle status of the concept: Draft, Proposed, Provisional, Approved, or Deprecated.';

COMMENT ON COLUMN __mj."GraphEdge"."Status" IS 'Governance lifecycle status of the edge: Proposed, Provisional, Approved, or Rejected. Default graph traversal includes Approved edges only.';

-- ===================== HAND-FINISHED (spDeleteEntityWithCoreDependencies) =====================
CREATE OR REPLACE FUNCTION __mj."spDeleteEntityWithCoreDependencies"(p_EntityID uuid)
RETURNS SETOF record
LANGUAGE plpgsql
AS $spdel$
DECLARE
    -- The policy's delete and null references (packages/CodeGenLib/src/__tests__/fixtures/entity-delete-fk-policy.json).
    v_handled  text[] := ARRAY[
        'AccessControlRule.EntityID',
        'ActionExecutionLog.TargetEntityID',
        'AIAgentContextItem.ItemEntityID',
        'AIAgentLearningCycleProposal.AppliedEntityID',
        'AIAgentLearningCycleProposal.PrimaryScopeEntityID',
        'AIAgentLearningCycleProposalSource.SourceEntityID',
        'AIAgentExample.PrimaryScopeEntityID',
        'AIAgentNote.PrimaryScopeEntityID',
        'AIAgentRun.PrimaryScopeEntityID',
        'AIAgentSession.LinkedEntityID',
        'ApplicationEntity.EntityID',
        'ArchiveConfigurationEntity.EntityID',
        'ArchiveRunDetail.EntityID',
        'Artifact.DelegateEntityID',
        'AuditLog.EntityID',
        'CalendarEventLink.EntityID',
        'ClusterAnalysis.EntityID',
        'CommunicationEndpointPrincipal.EntityID',
        'CommunicationLog.EntityID',
        'CommunicationPrincipal.EntityID',
        'CommunicationPrincipalPreference.EntityID',
        'CommunicationSenderType.EntityID',
        'CommunicationSuppression.EntityID',
        'CompanyIntegrationEntityMap.EntityID',
        'CompanyIntegrationRecordMap.EntityID',
        'CompanyIntegrationRunDetail.EntityID',
        'ContentSource.EntityID',
        'Conversation.LinkedEntityID',
        'DataContextItem.EntityID',
        'DatasetItem.EntityID',
        'DuplicateRun.EntityID',
        'EntityAction.EntityID',
        'EntityAction.ScopeEntityID',
        'EntityAIAction.EntityID',
        'EntityAIAction.OutputEntityID',
        'EntityAlternateBaseView.EntityID',
        'EntityCommunicationMessageType.EntityID',
        'EntityDocument.EntityID',
        'EntityField.EntityID',
        'EntityField.RelatedEntityID',
        'EntityFormContribution.EntityID',
        'EntityFormContribution.RelatedEntityID',
        'EntityFormOverride.EntityID',
        'EntityOrganicKey.EntityID',
        'EntityOrganicKeyRelatedEntity.RelatedEntityID',
        'EntityPermission.EntityID',
        'EntityRecordDocument.EntityID',
        'EntityRelationship.EntityID',
        'EntityRelationship.RelatedEntityID',
        'EntitySetting.EntityID',
        'EntityUniqueKey.EntityID',
        'FeatureValue.EntityID',
        'FileEntityRecordLink.EntityID',
        'FormChromeRule.EntityID',
        'FormChromeRule.RelatedEntityID',
        'GraphEdge.SourceEntityID',
        'GraphEdge.TargetEntityID',
        'GraphEdgeTypeEndpoint.EntityID',
        'GeneratedCode.LinkedEntityID',
        'IdentityClaim.EntityID',
        'IntegrationURLFormat.EntityID',
        'InteractionLink.EntityID',
        'List.EntityID',
        'MaterializedResult.GeneratedEntityID',
        'MaterializedResult.SourceEntityID',
        'MLModelScoringBinding.TargetEntityID',
        'MLScoringRun.ScopeEntityID',
        'MLTrainingPipeline.TargetEntityID',
        'ProcessRunDetail.EntityID',
        'ProcessRun.EntityID',
        'QueryEntity.EntityID',
        'QueryField.SourceEntityID',
        'RecommendationItem.DestinationEntityID',
        'Recommendation.SourceEntityID',
        'RecordArtifact.EntityID',
        'RecordChange.EntityID',
        'RecordCloneLogItem.EntityID',
        'RecordCloneLog.RootEntityID',
        'RecordGeoCode.EntityID',
        'RecordLink.SourceEntityID',
        'RecordLink.TargetEntityID',
        'RecordMergeLog.EntityID',
        'RecordProcess.EntityID',
        'RecordProcessWatermark.EntityID',
        'ResourceType.CategoryEntityID',
        'ResourceType.EntityID',
        'RubricEvaluation.ContextEntityID',
        'RubricEvaluation.SubjectEntityID',
        'ScopedNotificationConfig.PrimaryScopeEntityID',
        'ScopedPromptConfig.PrimaryScopeEntityID',
        'ScopedPromptPart.PrimaryScopeEntityID',
        'SearchScopeEntity.EntityID',
        'SignatureRequest.EntityID',
        'SystemEvent.EntityID',
        'TaggedItem.EntityID',
        'TagScope.ScopeEntityID',
        'TemplateParam.EntityID',
        'TestRun.TargetLogEntityID',
        'UserApplicationEntity.EntityID',
        'UserFavorite.EntityID',
        'User.LinkedEntityID',
        'UserRecordLog.EntityID',
        'UserViewCategory.EntityID',
        'UserView.EntityID',
        'VersionLabel.EntityID',
        'VersionLabelItem.EntityID'
    ];
    v_ref      record;
    v_found    boolean;
    v_blockers text[] := ARRAY[]::text[];
    -- Rows this function deletes that other rows can reference, captured before any delete.
    v_EntityFieldIDs uuid[];
    v_UserViewIDs uuid[];
    v_UserViewCategoryIDs uuid[];
    v_UserViewRunIDs uuid[];
    v_ListIDs uuid[];
    v_EntityDocumentIDs uuid[];
    v_EntityRecordDocumentIDs uuid[];
    v_DuplicateRunIDs uuid[];
    v_DuplicateRunDetailIDs uuid[];
    v_EntityActionIDs uuid[];
    v_AlternateBaseViewIDs uuid[];
    v_MessageTypeIDs uuid[];
    v_OrganicKeyIDs uuid[];
    v_CommsPrincipalIDs uuid[];
    v_CommsPreferenceIDs uuid[];
    v_CommsSuppressionIDs uuid[];
    v_IntegrationEntityMapIDs uuid[];
    v_IntegrationRunDetailIDs uuid[];
    v_PipelineIDs uuid[];
    v_MLModelIDs uuid[];
    v_ProcessRunDetailIDs uuid[];
    v_RecommendationIDs uuid[];
    v_RecordCloneLogIDs uuid[];
    v_RecordMergeLogIDs uuid[];
    v_RecordProcessIDs uuid[];
    v_RubricEvaluationIDs uuid[];
    v_ResourceTypeIDs uuid[];
    v_AgentNoteIDs uuid[];
    v_AgentExampleIDs uuid[];
    v_ScopedPromptPartIDs uuid[];
    v_GraphEdgeIDs uuid[];
    v_ProposalIDs uuid[];
BEGIN
    -- ── Precondition: refuse to start if something not covered by the policy points at this entity ──
    -- Only NO ACTION / RESTRICT foreign keys can block the final DELETE (confdeltype 'a' / 'r');
    -- CASCADE, SET NULL and SET DEFAULT are cleared by PostgreSQL itself.
    FOR v_ref IN
        SELECT DISTINCT n.nspname AS sch, t.relname AS tbl, a.attname AS col
        FROM pg_constraint c
        JOIN pg_class t     ON t.oid = c.conrelid
        JOIN pg_namespace n ON n.oid = t.relnamespace
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.contype = 'f'
          AND c.confrelid = '__mj."Entity"'::regclass
          AND c.confdeltype IN ('a', 'r')
          AND NOT (n.nspname = '__mj' AND (t.relname || '.' || a.attname) = ANY (v_handled))
        ORDER BY 1, 2, 3
    LOOP
        EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I.%I WHERE %I = $1)', v_ref.sch, v_ref.tbl, v_ref.col)
            INTO v_found USING p_EntityID;
        IF v_found THEN
            v_blockers := v_blockers || (v_ref.sch || '.' || v_ref.tbl || '.' || v_ref.col);
        END IF;
    END LOOP;

    IF cardinality(v_blockers) > 0 THEN
        RAISE EXCEPTION 'Cannot delete entity %: rows still reference it through foreign keys this procedure does not clear (%). Clear them first. Nothing has been deleted.',
            p_EntityID, left(array_to_string(v_blockers, ', '), 1600);
    END IF;

    -- ── Rows this function deletes that other rows can reference: capture their IDs up front ──
    v_EntityFieldIDs := ARRAY(SELECT "ID" FROM __mj."EntityField" WHERE "EntityID" = p_EntityID);

    v_UserViewIDs := ARRAY(SELECT "ID" FROM __mj."UserView" WHERE "EntityID" = p_EntityID);

    v_UserViewCategoryIDs := ARRAY(SELECT "ID" FROM __mj."UserViewCategory" WHERE "EntityID" = p_EntityID);

    v_UserViewRunIDs := ARRAY(SELECT "ID" FROM __mj."UserViewRun" WHERE "UserViewID" = ANY (v_UserViewIDs));

    v_ListIDs := ARRAY(SELECT "ID" FROM __mj."List" WHERE "EntityID" = p_EntityID);

    v_EntityDocumentIDs := ARRAY(SELECT "ID" FROM __mj."EntityDocument" WHERE "EntityID" = p_EntityID);

    v_EntityRecordDocumentIDs := ARRAY(SELECT "ID" FROM __mj."EntityRecordDocument"
        WHERE "EntityID" = p_EntityID OR "EntityDocumentID" = ANY (v_EntityDocumentIDs));

    v_DuplicateRunIDs := ARRAY(SELECT "ID" FROM __mj."DuplicateRun"
        WHERE "EntityID" = p_EntityID OR "EntityDocumentID" = ANY (v_EntityDocumentIDs));

    v_DuplicateRunDetailIDs := ARRAY(SELECT "ID" FROM __mj."DuplicateRunDetail"
        WHERE "DuplicateRunID" = ANY (v_DuplicateRunIDs));

    v_EntityActionIDs := ARRAY(SELECT "ID" FROM __mj."EntityAction"
        WHERE "EntityID" = p_EntityID OR "ScopeEntityID" = p_EntityID);

    v_AlternateBaseViewIDs := ARRAY(SELECT "ID" FROM __mj."EntityAlternateBaseView" WHERE "EntityID" = p_EntityID);

    v_MessageTypeIDs := ARRAY(SELECT "ID" FROM __mj."EntityCommunicationMessageType" WHERE "EntityID" = p_EntityID);
    -- Communications V2: rows keyed to a record of this entity
    v_CommsPrincipalIDs := ARRAY(SELECT "ID" FROM __mj."CommunicationPrincipal" WHERE "EntityID" = p_EntityID);
    v_CommsPreferenceIDs := ARRAY(SELECT "ID" FROM __mj."CommunicationPrincipalPreference" WHERE "EntityID" = p_EntityID);
    -- Only principal-only suppressions go with the entity. A suppression that also names an endpoint
    -- (a hard bounce or spam complaint recorded against a principal) keeps blocking that address.
    v_CommsSuppressionIDs := ARRAY(SELECT "ID" FROM __mj."CommunicationSuppression" WHERE "EntityID" = p_EntityID AND "CommunicationEndpointID" IS NULL);

    v_OrganicKeyIDs := ARRAY(SELECT "ID" FROM __mj."EntityOrganicKey" WHERE "EntityID" = p_EntityID);

    v_IntegrationEntityMapIDs := ARRAY(SELECT "ID" FROM __mj."CompanyIntegrationEntityMap" WHERE "EntityID" = p_EntityID);

    v_IntegrationRunDetailIDs := ARRAY(SELECT "ID" FROM __mj."CompanyIntegrationRunDetail" WHERE "EntityID" = p_EntityID);

    v_PipelineIDs := ARRAY(SELECT "ID" FROM __mj."MLTrainingPipeline" WHERE "TargetEntityID" = p_EntityID);

    v_MLModelIDs := ARRAY(SELECT "ID" FROM __mj."MLModel" WHERE "PipelineID" = ANY (v_PipelineIDs));

    v_ProcessRunDetailIDs := ARRAY(SELECT "ID" FROM __mj."ProcessRunDetail" WHERE "EntityID" = p_EntityID);

    v_RecommendationIDs := ARRAY(SELECT "ID" FROM __mj."Recommendation" WHERE "SourceEntityID" = p_EntityID);

    v_RecordCloneLogIDs := ARRAY(SELECT "ID" FROM __mj."RecordCloneLog" WHERE "RootEntityID" = p_EntityID);

    v_RecordMergeLogIDs := ARRAY(SELECT "ID" FROM __mj."RecordMergeLog" WHERE "EntityID" = p_EntityID);

    v_RecordProcessIDs := ARRAY(SELECT "ID" FROM __mj."RecordProcess" WHERE "EntityID" = p_EntityID);

    v_RubricEvaluationIDs := ARRAY(SELECT "ID" FROM __mj."RubricEvaluation" WHERE "SubjectEntityID" = p_EntityID);

    v_ResourceTypeIDs := ARRAY(SELECT "ID" FROM __mj."ResourceType" WHERE "EntityID" = p_EntityID);

    v_AgentNoteIDs := ARRAY(SELECT "ID" FROM __mj."AIAgentNote" WHERE "PrimaryScopeEntityID" = p_EntityID);

