    MJConversationDetail_SourceConversationDetailID."ExternalID" AS "SourceConversationDetail",
    MJGraphConcept_SourceGraphConceptID."Name" AS "SourceGraphConcept",
    MJEntity_SourceEntityID."Name" AS "SourceEntity"
FROM
    "__mj"."AIAgentLearningCycleProposalSource" AS a
LEFT OUTER JOIN
    "__mj"."AIAgentLearningCycleProposal" AS MJAIAgentLearningCycleProposal_ProposalID
  ON
    "a"."ProposalID" = MJAIAgentLearningCycleProposal_ProposalID."ID"
LEFT OUTER JOIN
    "__mj"."AIAgentNote" AS MJAIAgentNote_SourceNoteID
  ON
    "a"."SourceNoteID" = MJAIAgentNote_SourceNoteID."ID"
LEFT OUTER JOIN
    "__mj"."AIAgentRun" AS MJAIAgentRun_SourceAgentRunID
  ON
    "a"."SourceAgentRunID" = MJAIAgentRun_SourceAgentRunID."ID"
LEFT OUTER JOIN
    "__mj"."ConversationDetail" AS MJConversationDetail_SourceConversationDetailID
  ON
    "a"."SourceConversationDetailID" = MJConversationDetail_SourceConversationDetailID."ID"
LEFT OUTER JOIN
