CREATE OR REPLACE FUNCTION "__mj"."spCreateAIAgentLearningCycle"(
    p_id UUID DEFAULT NULL,
    p_agentid UUID DEFAULT NULL,
    p_startedat TIMESTAMPTZ DEFAULT NULL,
    p_endedat_clear boolean DEFAULT false,
    p_endedat TIMESTAMPTZ DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL,
    p_agentsummary_clear boolean DEFAULT false,
    p_agentsummary TEXT DEFAULT NULL,
    p_cycletype varchar(30) DEFAULT NULL,
    p_companyid_clear boolean DEFAULT false,
    p_companyid UUID DEFAULT NULL,
    p_executedbyagentrunid_clear boolean DEFAULT false,
    p_executedbyagentrunid UUID DEFAULT NULL,
    p_proposalsgenerated int DEFAULT NULL,
    p_proposalsverified int DEFAULT NULL,
    p_proposalsapplied int DEFAULT NULL,
    p_totalcostusd_clear boolean DEFAULT false,
    p_totalcostusd decimal(10, 4) DEFAULT NULL
) RETURNS SETOF "__mj"."vwAIAgentLearningCycles" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."AIAgentLearningCycle"
        (
            "ID",
            "AgentID",
                "StartedAt",
                "EndedAt",
                "Status",
                "AgentSummary",
                "CycleType",
                "CompanyID",
                "ExecutedByAgentRunID",
                "ProposalsGenerated",
                "ProposalsVerified",
                "ProposalsApplied",
                "TotalCostUSD"
        )
    VALUES
        (
            v_new_id,
            p_agentid,
                COALESCE(p_startedat, NOW()),
                CASE WHEN p_endedat_clear = true THEN NULL ELSE COALESCE(p_endedat, NULL) END,
                p_status,
                CASE WHEN p_agentsummary_clear = true THEN NULL ELSE COALESCE(p_agentsummary, NULL) END,
                COALESCE(p_cycletype, 'Mixed'),
                CASE WHEN p_companyid_clear = true THEN NULL ELSE COALESCE(p_companyid, NULL) END,
                CASE WHEN p_executedbyagentrunid_clear = true THEN NULL ELSE COALESCE(p_executedbyagentrunid, NULL) END,
                COALESCE(p_proposalsgenerated, 0),
                COALESCE(p_proposalsverified, 0),
                COALESCE(p_proposalsapplied, 0),
                CASE WHEN p_totalcostusd_clear = true THEN NULL ELSE COALESCE(p_totalcostusd, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwAIAgentLearningCycles"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
