    MJUser_CanonApprovedByUserID."Name" AS "CanonApprovedByUser",
    MJAIAgentLearningCycleProposal_OriginProposalID."Title" AS "OriginProposal"
FROM
    "__mj"."AISkill" AS a
LEFT OUTER JOIN
    "__mj"."User" AS MJUser_CreatedByUserID
  ON
    "a"."CreatedByUserID" = MJUser_CreatedByUserID."ID"
LEFT OUTER JOIN
    "__mj"."User" AS MJUser_CanonApprovedByUserID
  ON
    "a"."CanonApprovedByUserID" = MJUser_CanonApprovedByUserID."ID"
LEFT OUTER JOIN
